/* Release QA hardening for the static, local-only BillCart demonstration. */
function bcEscape(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function bcGstOk(v){return [0,5,12,18,28].includes(Number(v))}
function bcCouponOk(c){if(!c||!['percent','fixed','shipping'].includes(c.type))return false;const v=Number(c.value),m=c.min===undefined?0:Number(c.min),x=c.max===undefined?undefined:Number(c.max),uses=Number(c.uses||0),maxUses=c.maxUses===undefined?undefined:Number(c.maxUses),perCustomer=c.maxPerCustomer===undefined?1:Number(c.maxPerCustomer);return Number.isFinite(v)&&v>=0&&Number.isFinite(m)&&m>=0&&(c.type!=='percent'||v>0&&v<=100)&&(c.type!=='fixed'||v>0)&&(x===undefined||Number.isFinite(x)&&x>=0&&(c.type!=='percent'||x>0))&&(!c.expiry||/^\d{4}-\d{2}-\d{2}$/.test(c.expiry)&&!Number.isNaN(Date.parse(c.expiry)))&&Number.isInteger(uses)&&uses>=0&&(maxUses===undefined||Number.isInteger(maxUses)&&maxUses>0)&&Number.isInteger(perCustomer)&&perCustomer>0}function bcCouponAvailable(c,userId){if(!bcCouponOk(c)||c.active===false)return false;const today=new Date().toISOString().slice(0,10);if(c.expiry&&c.expiry<today)return false;if(c.maxUses!==undefined&&Number(c.uses||0)>=Number(c.maxUses))return false;return !userId||Number(c.usageByUser?.[userId]||0)<Number(c.maxPerCustomer||1)}
function bcDescription(p){const t=p.name,b=p.brand||p.b,options={Electronics:[`Sample electronics listing for ${t} from ${b}. Confirm compatibility and included accessories before purchase.`,`Demo technology entry: ${t} by ${b}. Technical specifications are illustrative; confirm them with a seller.`,`Explore ${t}, a sample ${b} electronics listing. Check the actual specifications before ordering.`],Fashion:[`Sample fashion listing: ${t} by ${b}. Confirm size and material information with a seller.`,`Demo apparel entry for ${t} from ${b}; fit and fabric details are not verified.`,`Explore ${t}, a sample ${b} fashion listing. Check sizing before ordering.`],'Home & Kitchen':[`Sample home listing for ${t} from ${b}. Confirm dimensions and care instructions before purchase.`,`Demo household entry: ${t} by ${b}. Measurements and included parts are illustrative.`,`Explore ${t}, a sample ${b} home listing. Check dimensions before ordering.`],Grocery:[`Sample pantry listing for ${t} from ${b}. Check the actual package for ingredients, allergens and net weight.`,`Demo grocery entry: ${t} by ${b}; product composition and pack details are not verified.`,`Sample listing for ${t}. Verify ingredients and allergens on the delivered package.`],Beauty:[`Sample personal-care listing for ${t} by ${b}. Check real ingredients and directions before use.`,`Demo beauty entry: ${t} from ${b}; ingredients and product claims are not verified.`,`Sample listing for ${t}. Review the actual label for ingredients and directions.`],Sports:[`Sample sports listing for ${t} from ${b}. Confirm sizing, materials and intended use before purchase.`,`Demo sporting-goods entry: ${t} by ${b}; specifications are illustrative.`,`Sample listing for ${t}. Confirm compatibility and safety details with a seller.`],Accessories:[`Sample accessory listing for ${t} by ${b}. Confirm dimensions and compatibility before ordering.`,`Demo accessory entry for ${t}; materials and specifications are not verified.`,`Sample listing for ${t}. Check fit and compatibility with a seller.`]};const list=options[p.category]||options.Accessories;return list[Number(p.id)%list.length]}
function bcImage(p){const raw=String(p?.image||'');if(raw.startsWith('data:image/svg+xml;charset=UTF-8,'))return raw;try{const url=new URL(raw);if(url.protocol==='https:'&&['images.unsplash.com','images.pexels.com','upload.wikimedia.org'].includes(url.hostname))return raw}catch{}return productFallback(p)}
function bcProductValid(p){return !!p&&Number.isSafeInteger(Number(p.id))&&!!p.name&&!!p.category&&Number.isFinite(Number(p.p))&&Number(p.p)>0&&Number.isFinite(Number(p.old))&&Number(p.old)>=Number(p.p)&&bcGstOk(p.gstRate)&&Number.isInteger(Number(p.stock))&&Number(p.stock)>=0&&!!p.brand&&!!p.image}
for(const p of products){p.gstRate=bcGstOk(p.gstRate)?Number(p.gstRate):(p.c==='Grocery'?5:18);p.description=bcDescription(p);p.reviewCount=0;p.sku=p.sku||`BC-${String(p.id).padStart(4,'0')}`;p.image=bcImage(p)}
let bcRemovedPassword=false;for(const user of Object.values(state.users||{}))if(user&&Object.hasOwn(user,'password')){delete user.password;bcRemovedPassword=true}if(bcRemovedPassword)save();
let bcOrderLock=false,bcEditAddress=-1,bcEditingCoupon='';
function bcUserId(email){email=String(email||'').trim().toLowerCase();if(['customer@billcart.com','admin@billcart.com'].includes(email))return 'usr-'+email.replace(/[^a-z0-9]/g,'');return Object.keys(state.users).find(k=>String(state.users[k]?.profile?.email||'').toLowerCase()===email)||'usr-'+encodeURIComponent(email)}
function switchUser(user){if(state.user)save();state.user=user;const saved=state.users[user.id]||{};state.cart=Array.isArray(saved.cart)?saved.cart:[];state.wish=Array.isArray(saved.wish)?saved.wish:[];state.addresses=Array.isArray(saved.addresses)?saved.addresses:[];state.coupon='';state.checkout={paymentMethod:'UPI'};save()}
function validProduct(p){return bcProductValid(p)}
function bill(){const rows=state.cart.map(x=>({p:products.find(p=>p.id===Number(x.id)),q:Number(x.q)}));if(rows.some(({p,q})=>!validProduct(p)||!Number.isInteger(q)||q<1))return{sub:0,productDiscount:0,coupon:0,taxable:0,cgst:0,sgst:0,delivery:0,total:0,valid:false};const r=n=>Math.round((n+Number.EPSILON)*100)/100,sub=r(rows.reduce((n,{p,q})=>n+p.p*q,0)),productDiscount=r(rows.reduce((n,{p,q})=>n+Math.max(0,p.old-p.p)*q,0));let coupon=0,delivery=sub>=999?0:sub?79:0;const c=state.coupon?state.coupons?.[state.coupon]:null;if(state.coupon&&(!bcCouponAvailable(c,state.user?.id)||sub<Number(c.min||0)))return{sub,productDiscount,coupon:0,taxable:sub,cgst:0,sgst:0,delivery,total:0,valid:false};if(c?.type==='percent')coupon=Math.min(sub*c.value/100,c.max??Infinity);if(c?.type==='fixed')coupon=Math.min(sub,c.value,c.max??Infinity);if(c?.type==='shipping')delivery=0;coupon=r(coupon);const taxable=r(Math.max(0,sub-coupon)),weighted=rows.reduce((n,{p,q})=>n+p.p*q*p.gstRate,0),gst=r(taxable*(sub?weighted/sub:0)/100),cgst=r(gst/2),sgst=r(gst-cgst);return{sub,productDiscount,coupon,taxable,cgst,sgst,delivery:r(delivery),total:r(taxable+gst+delivery),valid:true}}
function nav(){const dest=state.user?.role==='admin'?'admin':state.user?'dashboard':'login',acct=state.user?`<button onclick="go('${dest}')">◉ ${bcEscape(state.user.name.split(' ')[0])}</button><button onclick="logout()">Logout</button>`:`<button onclick="go('login')">Login</button>`;return `<nav class="nav"><div class="wrap"><button class="logo" onclick="go('home')"><b>✓</b>BillCart</button><div class="navlinks"><button onclick="go('home')">Home</button><button onclick="go('shop')">Shop</button><button onclick="go('offers')">Coupons & Offers</button><button onclick="go('orders')">Orders</button></div><div class="search"><input id="search" oninput="search(this.value)" placeholder="Search products…"></div><div class="icons"><button onclick="go('wishlist')">♡ ${state.wish.length}</button><button onclick="go('cart')">Cart ${state.cart.reduce((n,x)=>n+x.q,0)}</button><button onclick="toggleTheme()">${state.dark?'☀':'◐'}</button>${acct}</div></div></nav>`}
function productCard(p){if(!validProduct(p))return '';return `<article class="card"><button class="wish" onclick="wish(${p.id})" aria-label="Toggle wishlist">${state.wish.includes(p.id)?'♥':'♡'}</button><button class="product-img" onclick="go('product',${p.id})" aria-label="View ${bcEscape(p.name)}"><img src="${bcEscape(bcImage(p))}" alt="${bcEscape(p.name)} ${p.imageFallback?'image unavailable':'product photo'}" data-product-id="${p.id}" loading="lazy" onerror="bcProductImageError(this,${p.id})"></button><div class="card-body"><div class="brand">${bcEscape(p.brand)}</div><div class="name">${bcEscape(p.name)}</div><div class="rating">Demo rating ★ ${Number(p.rating).toFixed(1)} / 5 (illustrative)</div><div class="price">${money(p.p)} <span class="old">${money(p.old)}</span></div><div class="card-foot"><span class="stock">${p.stock?'In stock':'Out of stock'}</span><button class="btn" ${p.stock?'':'disabled'} onclick="add(${p.id})">${p.stock?'Add':'Sold out'}</button></div></div></article>`}
function notFound(message='Page not found'){return `${nav()}<main class="wrap"><section class="panel empty"><h1>Not found</h1><p>${bcEscape(message)}</p><button class="btn" onclick="go('shop')">Browse products</button></section></main><div class="toast hidden"></div>`}
function details(id){const p=products.find(x=>x.id===Number(id));if(!validProduct(p))return notFound('This product ID is not in the catalogue.');return `${nav()}<main class="wrap"><button class="link" onclick="go('shop')">← Shop</button><div class="cart-layout"><section class="panel"><div class="product-img" style="height:360px"><img src="${bcEscape(bcImage(p))}" alt="${bcEscape(p.name)} ${p.imageFallback?'image unavailable':'product photo'}" data-product-id="${p.id}" onerror="bcProductImageError(this,${p.id})"></div><p class="muted">Sample catalogue image and information.</p></section><section class="panel"><div class="brand">${bcEscape(p.brand)} · SKU ${bcEscape(p.sku)}</div><h1>${bcEscape(p.name)}</h1><p>Demo rating ${Number(p.rating).toFixed(1)} / 5 · sample only, no verified reviews</p><div class="price">${money(p.p)} · ${Number(p.discount)||0}% off</div><p>${bcEscape(p.description)}</p><p>Demo GST ${p.gstRate}% · Sample HSN ${bcEscape(p.hsn||'not supplied')} (unverified)</p><button class="btn" onclick="add(${p.id})" ${p.stock?'':'disabled'}>Add to Cart</button><button class="btn secondary" onclick="wish(${p.id})">Wishlist</button></section></div><div class="grid">${products.filter(x=>x.c===p.c&&x.id!==p.id).slice(0,4).map(productCard).join('')}</div></main><div class="toast hidden"></div>`}
function cart(){if(!state.user)return login();const b=bill();if(!b.valid)return `${nav()}<main class="wrap"><section class="panel empty"><h2>Cart needs attention</h2><p>Review cart quantities or remove an invalid coupon before checkout.</p>${state.coupon?`<button class="btn secondary" onclick="removeCoupon()">Remove ${bcEscape(state.coupon)}</button>`:''}<button class="btn secondary" onclick="go('shop')">Continue shopping</button></section></main>`;return `${nav()}<main class="wrap"><h2>My Cart · demo tax estimate</h2>${state.cart.length?`<div class="cart-layout"><section class="panel">${state.cart.map(x=>{const p=products.find(p=>p.id===x.id);return `<div class="cart-item"><img class="fakeimg" src="${bcEscape(bcImage(p))}" alt="${bcEscape(p.name)} ${p.imageFallback?'image unavailable':'product photo'}" data-product-id="${p.id}" onerror="bcProductImageError(this,${p.id})"><div style="flex:1"><b>${bcEscape(p.name)}</b><p>Demo GST ${p.gstRate}%</p>${money(p.p)}</div><div class="qty"><button onclick="qty(${p.id},-1)">−</button>${x.q}<button onclick="qty(${p.id},1)">+</button></div><button onclick="remove(${p.id})">Remove</button></div>`}).join('')}</section><aside class="panel summary">${state.coupon?`<p>Coupon ${bcEscape(state.coupon)} · −${money(b.coupon)} <button class="link" onclick="removeCoupon()">Remove</button></p>`:`<div class="coupon"><input id="coupon" placeholder="Coupon code"><button class="btn" onclick="applyCoupon()">Apply</button></div>`}<button class="link" onclick="bestCoupon()">Find best coupon for this cart</button><p>Subtotal ${money(b.sub)}</p><p>Product savings −${money(b.productDiscount)}</p><p>Coupon discount −${money(b.coupon)}</p><p>Taxable ${money(b.taxable)}</p><p>CGST + SGST (demo rates) ${money(b.cgst+b.sgst)}</p><p>Delivery ${money(b.delivery)}</p><h3>Total ${money(b.total)}</h3><button class="btn" onclick="go('checkout')">Checkout</button></aside></div>`:'<section class="panel empty"><p>Cart is empty.</p><button class="btn" onclick="go(\'shop\')">Shop</button></section>'}</main><div class="toast hidden"></div>`}
function selectCheckoutAddress(i){if(i===''){if(state.checkout)delete state.checkout.addressIndex;for(const id of ['full','phone','address','city','region','pin']){const el=document.querySelector('#'+id);if(el)el.value=id==='full'?state.user?.name||'':''}return}const a=state.addresses[Number(i)];if(!a)return;for(const [id,v] of Object.entries({full:a.name,phone:a.phone,address:a.address,city:a.city,region:a.state,pin:a.pincode})){const el=document.querySelector('#'+id);if(el)el.value=v}state.checkout={...(state.checkout||{}),addressIndex:Number(i)}}
function checkout(){if(!state.user||state.user.role==='admin')return go('login');const b=bill();if(!state.cart.length||!b.valid)return go('cart');const a=state.addresses[state.checkout?.addressIndex]||{},profile=state.profiles[state.user.id]||{},val=(key,fallback='')=>bcEscape(a[key]||profile[key]||fallback),payment=state.checkout?.paymentMethod||'UPI';return `${nav()}<main class="wrap checkout"><div class="checkout-layout"><section class="panel checkout-form"><div class="eyebrow">Secure demo checkout</div><h2>Delivery & billing details</h2>${state.addresses.length?`<label>Saved address<select id="addressSelect" onchange="selectCheckoutAddress(this.value)"><option value="">Enter address</option>${state.addresses.map((x,i)=>`<option value="${i}" ${Number(state.checkout?.addressIndex)===i?'selected':''}>${bcEscape(x.name)} · ${bcEscape(x.city)} · ${bcEscape(x.pincode)}</option>`).join('')}</select></label>`:''}<div class="form-grid"><label>Name<input id="full" maxlength="100" value="${val('name',state.user.name)}" autocomplete="name" required></label><label>Phone<input id="phone" inputmode="numeric" maxlength="10" value="${val('phone')}" autocomplete="tel" required></label><label>Street address<input id="address" maxlength="200" value="${val('address')}" autocomplete="street-address" required></label><label>City<input id="city" maxlength="80" value="${val('city')}" autocomplete="address-level2" required></label><label>State<input id="region" maxlength="80" value="${val('state')}" autocomplete="address-level1" required></label><label>Postal code<input id="pin" inputmode="numeric" maxlength="6" value="${val('pincode')}" autocomplete="postal-code" required></label><label>Country<input value="India" autocomplete="country-name" readonly></label></div><label><input type="checkbox" id="saveAddressOnOrder"> Save this address to My Account</label><h3>Payment method</h3>${['UPI','Card','Cash on Delivery'].map(x=>`<label class="payment-option"><input type="radio" name="paymentMethod" value="${x}" ${payment===x?'checked':''} onchange="setPayment(this.value)">${x} <span class="muted">demo</span></label>`).join('')}<label>Simulated payment outcome<select id="demoPayment"><option value="success">Success</option><option value="failure">Failure</option><option value="cancel">Cancelled</option></select></label><p class="muted">Simulation only. No card details are requested, no payment is taken, and no gateway is contacted.</p><button id="placeOrderButton" class="btn" onclick="placeOrder()">Place demo order · ${money(b.total)}</button> <button class="btn secondary" onclick="go('cart')">Return to cart</button></section><aside class="panel checkout-summary"><div class="section-head"><div><div class="eyebrow">Review</div><h2>Order summary</h2></div><button class="link" onclick="go('cart')">Edit cart</button></div>${state.cart.map(x=>{const p=products.find(y=>y.id===Number(x.id));return `<div class="checkout-item"><img src="${bcEscape(bcImage(p))}" alt="${bcEscape(p.name)}" data-product-id="${p.id}" onerror="bcProductImageError(this,${p.id})"><div><b>${bcEscape(p.name)}</b><span>Qty ${x.q} · ${money(p.p)} each</span><span>Demo GST ${p.gstRate}%</span></div><b>${money(p.p*x.q)}</b></div>`}).join('')}<hr><div class="line"><span>Subtotal</span><b>${money(b.sub)}</b></div><div class="line"><span>Product savings</span><span>−${money(b.productDiscount)}</span></div><div class="line"><span>Coupon${state.coupon?` · ${bcEscape(state.coupon)}`:''}</span><span>−${money(b.coupon)}</span></div><div class="line"><span>Taxable amount</span><span>${money(b.taxable)}</span></div><div class="line"><span>CGST + SGST (demo)</span><span>${money(b.cgst+b.sgst)}</span></div><div class="line"><span>Delivery</span><span>${b.delivery?money(b.delivery):'Free'}</span></div><div class="line total"><span>Payable total</span><b>${money(b.total)}</b></div><p class="muted">Sample tax rates only. Verify applicable tax on an actual purchase.</p></aside></div></main><div class="toast hidden"></div>`}function bcReadAddress(){const v=Object.fromEntries(['full','phone','address','city','region','pin'].map(id=>[id,(document.querySelector('#'+id)?.value||'').trim()]));if(v.full.length<2||v.full.length>100||!/^\d{10}$/.test(v.phone)||!v.address||v.address.length>200||!v.city||v.city.length>80||!v.region||v.region.length>80||!/^\d{6}$/.test(v.pin))return null;return{name:v.full,phone:v.phone,address:v.address,city:v.city,state:v.region,pincode:v.pin}}
function bcNewOrderId(){let token='';try{token=crypto.randomUUID()}catch{token=Math.random().toString(36).slice(2)+Math.random().toString(36).slice(2)}return 'BC-'+Date.now().toString(36).toUpperCase()+'-'+token.replace(/-/g,'').slice(0,16).toUpperCase()}
function placeOrder(){if(bcOrderLock)return toast('Order submission is already running.');if(!state.user||state.user.role==='admin')return go('login');const address=bcReadAddress();if(!address)return toast('Enter a valid name, phone, complete address, city, state and six digit pincode.');if(!state.cart.length)return go('cart');const b=bill();if(!b.valid||![b.sub,b.taxable,b.cgst,b.sgst,b.delivery,b.total].every(Number.isFinite)||b.total<0)return toast('Invalid billing data; review your cart and coupon.');const method=state.checkout?.paymentMethod||document.querySelector('input[name="paymentMethod"]:checked')?.value,outcome=document.querySelector('#demoPayment')?.value||'success';if(!['UPI','Card','Cash on Delivery'].includes(method))return toast('Select a payment method.');if(!['success','failure','cancel'].includes(outcome))return toast('Select a valid demo outcome.');if(method!=='Cash on Delivery'&&outcome==='failure')return toast('Demo payment failed. No order was created; retry checkout.');if(method!=='Cash on Delivery'&&outcome==='cancel')return toast('Demo payment cancelled. No order was created; your cart is unchanged.');const rows=state.cart.map(x=>({p:products.find(p=>p.id===Number(x.id)),q:Number(x.q)}));if(rows.some(({p,q})=>!validProduct(p)||!Number.isInteger(q)||q<1||q>p.stock))return toast('Stock changed; review the cart.');bcOrderLock=true;const button=document.querySelector('#placeOrderButton');if(button)button.disabled=true;try{const id=bcNewOrderId(),items=rows.map(({p,q})=>({id:p.id,name:p.name,sku:p.sku,image:p.image,imageFallback:p.imageFallback,category:p.category,unitPrice:p.p,price:p.p,originalPrice:p.old,quantity:q,q,discount:p.discount,hsn:p.hsn||'Unverified sample',gstRate:p.gstRate}));if(state.orders.some(o=>o.id===id||o.orderId===id))throw Error('Order ID collision');const order={id,orderId:id,invoiceNumber:'INV-'+id,verificationReference:id,userId:state.user.id,customer:state.user.name,items,couponCode:state.coupon||'',subtotal:b.sub,productDiscount:b.productDiscount,couponDiscount:b.coupon,taxableAmount:b.taxable,cgst:b.cgst,sgst:b.sgst,gst:b.cgst+b.sgst,deliveryCharge:b.delivery,grandTotal:b.total,paymentMethod:method,paymentStatus:method==='Cash on Delivery'?'Demo payment pending':'Test payment succeeded',deliveryAddress:address,orderStatus:'Confirmed',createdAt:new Date().toISOString(),bill:{...b},stockRestored:false};state.orders.unshift(order);if(state.coupon){const used=state.coupons[state.coupon];used.uses=Number(used.uses||0)+1;used.usageByUser={...(used.usageByUser||{}),[state.user.id]:Number(used.usageByUser?.[state.user.id]||0)+1}}for(const {p,q} of rows)p.stock-=q;if(document.querySelector('#saveAddressOnOrder')?.checked&&!state.addresses.some(x=>x.phone===address.phone&&x.address===address.address&&x.pincode===address.pincode))state.addresses.push(address);state.cart=[];state.coupon='';state.checkout={paymentMethod:'UPI'};save();go('success',id)}catch(e){console.error(e);toast('Could not save order. Retry checkout.')}finally{bcOrderLock=false}}
function bcRestock(order){if(!order||order.stockRestored)return;for(const item of order.items||[]){const p=products.find(x=>x.id===Number(item.id));if(p)p.stock+=Number(item.quantity||item.q)||0}order.stockRestored=true}
function cancelOrder(id){const o=state.orders.find(x=>(x.orderId||x.id)===id&&x.userId===state.user?.id);if(!o||!['Confirmed','Processing','Shipped'].includes(o.orderStatus))return toast('This order cannot be cancelled.');bcRestock(o);o.orderStatus='Cancelled';save();go('orders')}
function requestReturn(id){const o=state.orders.find(x=>(x.orderId||x.id)===id&&x.userId===state.user?.id);if(!o||o.orderStatus!=='Delivered')return toast('Returns are available after delivery.');o.orderStatus='Return requested';save();go('orders')}
function setOrderStatus(id,status){const o=state.orders.find(x=>(x.orderId||x.id)===String(id).trim());if(!o||!['Confirmed','Processing','Shipped','Delivered','Cancelled'].includes(status))return toast('Invalid order status.');if(o.orderStatus==='Cancelled'||o.stockRestored)return toast('Cancelled orders cannot be reopened.');if(status==='Cancelled'){if(!['Confirmed','Processing','Shipped'].includes(o.orderStatus))return toast('Only unfulfilled orders can be cancelled.');bcRestock(o)}else if(o.orderStatus==='Delivered'&&status!=='Delivered')return toast('Delivered orders cannot change status here.');o.orderStatus=status;save();state.adminSection='Orders';go('admin')}
function signIn(){const email=(document.querySelector('#email')?.value||'').trim().toLowerCase(),pass=(document.querySelector('#password')?.value||'').trim();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return toast('Enter a valid email.');if(!pass)return toast('Enter a non-empty demo passphrase; never use a real password.');const id=bcUserId(email),admin=email==='admin@billcart.com';if(!state.users[id]&&!['customer@billcart.com','admin@billcart.com'].includes(email))return toast('No local demo account found. Register first.');const profile=state.users[id]?.profile||{};switchUser({id,name:admin?'Aarav Mehta':profile.name||(email==='customer@billcart.com'?'Priya Sharma':email.split('@')[0]),email,role:admin?'admin':'customer'});go(admin?'admin':'dashboard')}
function registerDemo(){document.querySelector('#app').innerHTML=`${nav()}<main class="wrap"><form class="panel auth" onsubmit="event.preventDefault();registerAccount()"><h2>Create local demo account</h2><p class="muted">Local storage is editable. Passphrases are not securely verified or saved. Never use a real password.</p><label>Name<input id="regName" required minlength="2" maxlength="100"></label><label>Email<input id="regEmail" required type="email" maxlength="254"></label><label>Demo passphrase<input id="regPassword" type="password" required minlength="6"></label><label>Phone<input id="regPhone" inputmode="numeric" pattern="[0-9]{10}" maxlength="10"></label><button class="btn">Create account</button></form></main><div class="toast hidden"></div>`}
function registerAccount(){const name=(document.querySelector('#regName')?.value||'').trim(),email=(document.querySelector('#regEmail')?.value||'').trim().toLowerCase(),pass=document.querySelector('#regPassword')?.value||'',phone=(document.querySelector('#regPhone')?.value||'').trim();if(name.length<2||name.length>100||!/^\d{10}$/.test(phone)&&phone||pass.length<6||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return toast('Check name, email, demo passphrase and optional phone.');const id=bcUserId(email);if(state.users[id]||['customer@billcart.com','admin@billcart.com'].includes(email))return toast('That email already has an account.');const user={id,name,email,role:'customer'};state.users[id]={cart:[],wish:[],addresses:[],profile:{name,email,phone}};state.profiles[id]={name,email,phone};switchUser(user);go('dashboard')}
function logout(){if(state.user)save();state.user=null;state.cart=[];state.wish=[];state.addresses=[];state.coupon='';state.checkout={paymentMethod:'UPI'};save();go('home')}
function login(){return `${nav()}<main class="wrap"><section class="panel auth"><h2>Local demo sign in</h2><p class="muted">Credentials are not securely checked. Passwords are not stored. Never use a real password; local storage is editable.</p><label>Email<input id="email" type="email" value="customer@billcart.com"></label><label>Demo passphrase<input id="password" type="password" value="demo123" autocomplete="off"></label><button class="link" onclick="toast('Password reset is unavailable in this demo. No email was sent.')">Forgot password?</button><button class="btn" onclick="signIn()">Sign in</button><button class="link" onclick="go('register')">Register</button><p>Built-in demo accounts: customer@billcart.com and admin@billcart.com (any non-empty demo text).</p></section></main><div class="toast hidden"></div>`}
function myAccount(){if(!state.user||state.user.role==='admin')return login();const profile=state.profiles[state.user.id]||{name:state.user.name,email:state.user.email},edit=bcEditAddress>=0?state.addresses[bcEditAddress]:null;return `${nav()}<main class="wrap"><h2>My Account</h2><section class="panel"><form onsubmit="event.preventDefault();saveProfile()"><label>Name<input id="profileName" maxlength="100" value="${bcEscape(profile.name||'')}" required></label><label>Email<input value="${bcEscape(profile.email||state.user.email)}" disabled></label><label>Phone<input id="profilePhone" inputmode="numeric" pattern="[0-9]{10}" value="${bcEscape(profile.phone||'')}"></label><button class="btn">Save profile</button></form></section><section class="panel"><h3>Addresses</h3>${state.addresses.map((a,i)=>`<p>${bcEscape(a.name)} · ${bcEscape(a.address)}, ${bcEscape(a.city)} ${bcEscape(a.pincode)} <button class="link" onclick="editAddress(${i})">Edit</button><button class="link" onclick="deleteAddress(${i})">Remove</button></p>`).join('')}<h3>${edit?'Edit':'Add'} address</h3><div class="form-grid"><input id="addrName" placeholder="Full name" value="${bcEscape(edit?.name||'')}"><input id="addrPhone" placeholder="10 digit phone" value="${bcEscape(edit?.phone||'')}"><input id="addrLine" placeholder="Street address" value="${bcEscape(edit?.address||'')}"><input id="addrCity" placeholder="City" value="${bcEscape(edit?.city||'')}"><input id="addrState" placeholder="State" value="${bcEscape(edit?.state||'')}"><input id="addrPin" placeholder="6 digit pincode" value="${bcEscape(edit?.pincode||'')}"></div><button class="btn" onclick="addAddress()">${edit?'Update':'Save'} address</button>${edit?'<button class="btn secondary" onclick="bcEditAddress=-1;go(\'account\')">Cancel</button>':''}</section></main>`}
function saveProfile(){const name=(document.querySelector('#profileName')?.value||'').trim(),phone=(document.querySelector('#profilePhone')?.value||'').trim();if(name.length<2||name.length>100||phone&&!/^\d{10}$/.test(phone))return toast('Check your name and optional 10 digit phone.');state.user.name=name;state.profiles[state.user.id]={...(state.profiles[state.user.id]||{}),name,email:state.user.email,phone};save();go('account')}
function editAddress(i){if(!state.addresses[i])return toast('Address not found.');bcEditAddress=Number(i);go('account')}
function addAddress(){const ids=['addrName','addrPhone','addrLine','addrCity','addrState','addrPin'],v=Object.fromEntries(ids.map(k=>[k,(document.querySelector('#'+k)?.value||'').trim()]));if(v.addrName.length<2||v.addrName.length>100||!/^\d{10}$/.test(v.addrPhone)||!v.addrLine||v.addrLine.length>200||!v.addrCity||v.addrCity.length>80||!v.addrState||v.addrState.length>80||!/^\d{6}$/.test(v.addrPin))return toast('Enter valid address details.');const a={name:v.addrName,phone:v.addrPhone,address:v.addrLine,city:v.addrCity,state:v.addrState,pincode:v.addrPin};if(bcEditAddress>=0&&state.addresses[bcEditAddress])state.addresses[bcEditAddress]=a;else state.addresses.push(a);bcEditAddress=-1;save();go('account')}
function deleteAddress(i){if(!Number.isInteger(Number(i))||!state.addresses[i])return toast('Address not found.');state.addresses.splice(i,1);save();go('account')}
function dashboard(){if(!state.user)return login();if(state.user.role==='admin')return admin();const mine=state.orders.filter(o=>o.userId===state.user.id),spent=mine.reduce((n,o)=>n+(Number(o.grandTotal)||0),0);return `${nav()}<main class="wrap"><h2>Welcome back, ${bcEscape(state.user.name)}</h2><div class="metrics"><div class="metric">Orders <b>${mine.length}</b></div><div class="metric">Wishlist <b>${state.wish.length}</b></div><div class="metric">Cart <b>${state.cart.reduce((n,x)=>n+x.q,0)}</b></div><div class="metric">Spent <b>${money(spent)}</b></div></div><section class="panel"><h3>Recent orders</h3>${mine.slice(0,5).map(o=>`<p>${bcEscape(o.orderId)} · ${bcEscape(o.orderStatus)} · ${money(o.grandTotal)}</p>`).join('')||'<p>No orders yet.</p>'}<button class="btn secondary" onclick="go('orders')">Orders</button><button class="btn secondary" onclick="go('account')">My Account</button><button class="btn secondary" onclick="go('wishlist')">Wishlist</button></section></main>`}
function wishlist(){if(!state.user||state.user.role==='admin')return login();const a=products.filter(p=>state.wish.includes(p.id));return `${nav()}<main class="wrap"><h2>Your wishlist</h2>${a.length?`<div class="grid">${a.map(productCard).join('')}</div>`:'<section class="panel empty">Wishlist is empty.</section>'}</main>`}
function orders(){if(!state.user)return login();const a=state.orders.filter(o=>state.user.role==='admin'||o.userId===state.user.id);return `${nav()}<main class="wrap"><h2>${state.user.role==='admin'?'All orders':'My orders'}</h2>${a.length?`<section class="panel"><table class="table"><thead><tr><th>Order</th><th>Date</th><th>Items</th><th>Total</th><th>Payment</th><th>Payment status</th><th>Order status</th><th>Actions</th></tr></thead><tbody>${a.map(o=>`<tr><td>${bcEscape(o.orderId||o.id)}</td><td>${bcEscape(o.createdAt||'')}</td><td>${(o.items||[]).map(i=>`<div class="order-item-preview"><img src="${bcEscape(bcImage({image:i.image,name:i.name}))}" alt="${bcEscape(i.name)} product photograph" data-product-id="${Number(i.id)||0}" onerror="bcProductImageError(this,${Number(i.id)||0})"><span>${bcEscape(i.name)} · ${bcEscape(i.sku||("Product "+i.id))} · ${Number(i.quantity||i.q)||0} × ${money(i.unitPrice??i.price)}</span></div>`).join("")}</td><td>${money(o.grandTotal)}</td><td>${bcEscape(o.paymentMethod)}</td><td>${bcEscape(o.paymentStatus)}</td><td>${bcEscape(o.orderStatus)}</td><td><button class="link" onclick="go('invoice','${bcEscape(o.orderId||o.id)}')">Invoice</button>${state.user.role==='admin'?'':`<button class="link" onclick="go('tracking','${bcEscape(o.orderId||o.id)}')">Track</button><button class="link" onclick="buyAgain('${bcEscape(o.orderId||o.id)}')">Buy again</button>${['Confirmed','Processing','Shipped'].includes(o.orderStatus)?`<button class="link" onclick="cancelOrder('${bcEscape(o.orderId||o.id)}')">Cancel</button>`:''}${o.orderStatus==='Delivered'?`<button class="link" onclick="requestReturn('${bcEscape(o.orderId||o.id)}')">Return</button>`:''}`}</td></tr>`).join('')}</tbody></table></section>`:'<section class="panel empty">No orders found.</section>'}</main>`}
function trackOrder(id){const o=state.orders.find(x=>(x.orderId||x.id)===id&&x.userId===state.user?.id);return o?`${nav()}<main class="wrap"><section class="panel"><h2>Simulated order status: ${bcEscape(o.orderId)}</h2><p>${bcEscape(o.orderStatus)}</p><p>This local status is simulated; no carrier tracking is connected.</p></section></main>`:notFound('Order not found for this account.')}
function success(id){const o=state.orders.find(x=>(x.orderId||x.id)===id&&x.userId===state.user?.id);return o?`${nav()}<main class="wrap"><section class="panel empty"><h1>Demo order created</h1><p>No payment was taken.</p><p>${bcEscape(o.orderId)} · ${money(o.grandTotal)}</p><button class="btn" onclick="go('invoice','${bcEscape(o.orderId)}')">Invoice</button><button class="btn secondary" onclick="go('orders')">Orders</button></section></main>`:notFound('Order not found.')}
function buyAgain(id){const o=state.orders.find(x=>(x.orderId||x.id)===id&&x.userId===state.user?.id);if(!o)return toast('Order not found.');for(const i of o.items||[]){const p=products.find(x=>x.id===Number(i.id));if(!p?.stock)continue;const q=Math.min(Number(i.quantity||i.q)||1,p.stock),c=state.cart.find(x=>x.id===p.id);if(c)c.q=Math.min(c.q+q,p.stock);else state.cart.push({id:p.id,q})}save();go('cart')}
function invoice(id){const o=state.orders.find(x=>(x.orderId||x.id)===id&&(state.user?.role==='admin'||x.userId===state.user?.id));if(!o){document.querySelector('#app').innerHTML=notFound('Invoice not found for this account.');return}const b=o.bill||{sub:o.subtotal||0,coupon:o.couponDiscount||0,taxable:o.taxableAmount||0,cgst:o.cgst??(o.gst||0)/2,sgst:o.sgst??(o.gst||0)/2,delivery:o.deliveryCharge||0,total:o.grandTotal||0};document.querySelector('#app').innerHTML=`${nav()}<main class="wrap"><div class="hero-actions"><button class="btn" onclick="downloadInvoicePdf('${bcEscape(o.orderId||o.id)}')">Download searchable PDF</button><button class="btn secondary" onclick="window.print()">Print</button></div><article class="invoice"><header class="invoice-header"><h1>BillCart demo invoice</h1><div>Invoice ${bcEscape(o.invoiceNumber||o.id)}<br>Order ${bcEscape(o.orderId||o.id)}<br>Demo ref ${bcEscape(o.verificationReference||o.id)}</div></header><p>Sample invoice only. No government GSTIN or online verification. Sample HSN/GST values are unverified.</p><p>${bcEscape(o.customer)}<br>${bcEscape(o.deliveryAddress?.address)}, ${bcEscape(o.deliveryAddress?.city)}, ${bcEscape(o.deliveryAddress?.state)} ${bcEscape(o.deliveryAddress?.pincode)}</p><div class="invoice-table-scroll" role="region" aria-label="Invoice line items" tabindex="0"><table><thead><tr><th>Item / sample HSN</th><th>Qty</th><th>Unit</th><th>Coupon share</th><th>Taxable line</th><th>Sample GST</th><th>Tax</th></tr></thead><tbody>${(()=>{const items=o.items||[],base=items.reduce((n,i)=>n+(Number(i.unitPrice??i.price)||0)*(Number(i.quantity||i.q)||0),0);return items.map(i=>{const q=Number(i.quantity||i.q)||0,p=Number(i.unitPrice??i.price)||0,r=bcGstOk(i.gstRate)?Number(i.gstRate):18,gross=p*q,share=base?Number(b.coupon||0)*gross/base:0,taxable=Math.max(0,gross-share),tax=taxable*r/100;return `<tr><td><img class="invoice-item-image" src="${bcEscape(bcImage({image:i.image,name:i.name}))}" alt="${bcEscape(i.name)} product photograph" data-product-id="${Number(i.id)||0}" onerror="bcProductImageError(this,${Number(i.id)||0})">${bcEscape(i.name)}<br>${bcEscape(i.hsn||'not supplied')} (unverified)</td><td>${q}</td><td>${money(p)}</td><td>${money(share)}</td><td>${money(taxable)}</td><td>${r}%</td><td>${money(tax)}</td></tr>`}).join('')})()}</tbody></table></div><p>Subtotal ${money(b.sub)} · Coupon −${money(b.coupon)} · Taxable ${money(b.taxable)} · CGST ${money(b.cgst)} · SGST ${money(b.sgst)} · Delivery ${money(b.delivery)}</p><h2>Total ${money(b.total)}</h2><p>Payment ${bcEscape(o.paymentMethod)} · ${bcEscape(o.paymentStatus)}. Demo reference only; not independently verifiable.</p></article></main>`}
function admin(){if(state.user?.role!=='admin')return login();const revenue=state.orders.reduce((n,o)=>n+(Number(o.grandTotal)||0),0);return `${nav()}<main class="wrap"><h2>Admin local demo</h2><div class="metrics"><div class="metric">Stored sales<b>${money(revenue)}</b></div><div class="metric">Stored orders<b>${state.orders.length}</b></div><div class="metric">Local accounts<b>${Object.keys(state.users).length}</b></div><div class="metric">Products<b>${products.length}</b></div></div><div class="panel">${['Dashboard','Products','Orders','Inventory','Customers','Coupons','Invoices','Reports','Settings'].map(x=>`<button class="btn secondary" onclick="adminPanel('${x}')">${x}</button>`).join('')}</div><section class="panel"><h3>Stored orders</h3>${state.orders.slice(0,10).map(o=>`<p>${bcEscape(o.orderId)} · ${bcEscape(o.customer)} · ${money(o.grandTotal)} · ${bcEscape(o.orderStatus)}</p>`).join('')||'<p>No demo orders stored.</p>'}</section></main>`}
function adminWorkspace(section){if(state.user?.role!=='admin')return login();let body='';if(section==='Products'||section==='Inventory')body=`<h2>${section} management</h2><div class="table-scroll"><table class="table"><thead><tr><th>SKU</th><th>Name</th><th>Price</th><th>GST demo %</th><th>Stock</th><th>Action</th></tr></thead><tbody>${products.map(p=>`<tr><td>${bcEscape(p.sku)}</td><td><input id="bc-name-${p.id}" value="${bcEscape(p.name)}" maxlength="120"></td><td><input id="bc-price-${p.id}" type="number" min="0.01" step="0.01" value="${p.p}"></td><td><select id="bc-gst-${p.id}">${[0,5,12,18,28].map(r=>`<option value="${r}" ${p.gstRate===r?'selected':''}>${r}</option>`).join('')}</select></td><td><input id="bc-stock-${p.id}" type="number" min="0" step="1" value="${p.stock}"></td><td><button class="link" onclick="updateProduct(${p.id})">Save</button></td></tr>`).join('')}</tbody></table></div><h3>Add sample product</h3><div class="form-grid"><input id="bc-new-name" maxlength="120" placeholder="Name"><select id="bc-new-category">${categories.map(([c])=>`<option>${bcEscape(c)}</option>`).join('')}</select><input id="bc-new-brand" maxlength="80" placeholder="Brand"><input id="bc-new-price" type="number" min="0.01" step="0.01" placeholder="Price"><input id="bc-new-stock" type="number" min="0" step="1" placeholder="Stock"><select id="bc-new-gst">${[0,5,12,18,28].map(r=>`<option value="${r}">${r}% demo</option>`).join('')}</select></div><button class="btn" onclick="createProduct()">Add product</button><p class="muted">Sample GST and HSN data are unverified; ratings are illustrative.</p>`;else if(section==='Orders')body=`<h2>Orders</h2><table class="table"><thead><tr><th>ID</th><th>Customer</th><th>Status</th><th>Change status</th></tr></thead><tbody>${state.orders.map(o=>`<tr><td>${bcEscape(o.orderId)}</td><td>${bcEscape(o.customer)}</td><td>${bcEscape(o.orderStatus)}</td><td><select onchange="setOrderStatus('${bcEscape(o.orderId)}',this.value)">${['Confirmed','Processing','Shipped','Delivered','Cancelled'].map(x=>`<option ${o.orderStatus===x?'selected':''}>${x}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table>`;else if(section==='Customers')body=`<h2>Local demo accounts</h2><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Orders</th></tr></thead><tbody>${Object.entries(state.users).map(([id,u])=>`<tr><td>${bcEscape(u.profile?.name||'Customer')}</td><td>${bcEscape(u.profile?.email||'')}</td><td>${state.orders.filter(o=>o.userId===id).length}</td></tr>`).join('')}</tbody></table>`;else if(section==='Coupons'){const edit=state.coupons[bcEditingCoupon]||{};body=`<h2>Coupon management</h2><p>Create demo coupons with expiry and usage limits. Counts are local to this browser.</p><div class="table-scroll"><table class="table"><thead><tr><th>Code</th><th>Type</th><th>Value</th><th>Minimum</th><th>Maximum</th><th>Expires</th><th>Uses</th><th>Status</th><th>Actions</th></tr></thead><tbody>${Object.entries(state.coupons).map(([code,c])=>`<tr><td>${bcEscape(code)}</td><td>${bcEscape(c.type)}</td><td>${c.type==='percent'?`${Number(c.value)}%`:c.type==='fixed'?money(c.value):'Free shipping'}</td><td>${money(c.min||0)}</td><td>${c.max===undefined?'—':money(c.max)}</td><td>${bcEscape(c.expiry||'No expiry')}</td><td>${Number(c.uses||0)}${c.maxUses?` / ${c.maxUses}`:''}</td><td>${c.active===false?'Inactive':'Active'}</td><td><button class="link" onclick="editCoupon('${bcEscape(code)}')">Edit</button><button class="link" onclick="toggleCoupon('${bcEscape(code)}')">${c.active===false?'Activate':'Deactivate'}</button></td></tr>`).join('')||'<tr><td colspan="9">No coupons created.</td></tr>'}</tbody></table></div><h3>${bcEditingCoupon?'Edit':'Create'} coupon</h3><div class="form-grid"><label>Code<input id="bc-coupon-code" maxlength="24" value="${bcEscape(bcEditingCoupon||'')}" placeholder="Code (3–24 letters or digits)"></label><label>Discount type<select id="bc-coupon-type"><option value="percent" ${edit.type==='percent'?'selected':''}>Percent</option><option value="fixed" ${edit.type==='fixed'?'selected':''}>Fixed amount</option><option value="shipping" ${edit.type==='shipping'?'selected':''}>Free shipping</option></select></label><label>Value<input id="bc-coupon-value" type="number" min="0" step="0.01" value="${edit.value??''}" placeholder="Value (0 for shipping)"></label><label>Minimum order value<input id="bc-coupon-min" type="number" min="0" step="0.01" value="${edit.min??''}" placeholder="Optional"></label><label>Maximum discount<input id="bc-coupon-max" type="number" min="0.01" step="0.01" value="${edit.max??''}" placeholder="Optional"></label><label>Expiry date<input id="bc-coupon-expiry" type="date" value="${bcEscape(edit.expiry||'')}"></label><label>Total use limit<input id="bc-coupon-limit" type="number" min="1" step="1" value="${edit.maxUses??''}" placeholder="Unlimited"></label><label>Uses per customer<input id="bc-coupon-per-customer" type="number" min="1" step="1" value="${edit.maxPerCustomer??1}"></label></div><button class="btn" onclick="createCoupon()">${bcEditingCoupon?'Save changes':'Create coupon'}</button><button class="btn secondary" onclick="generateCouponCode()">Generate unique code</button>${bcEditingCoupon?'<button class="btn secondary" onclick="cancelCouponEdit()">Cancel</button>':''}`}else if(section==='Invoices')body=`<h2>Stored invoices</h2>${state.orders.map(o=>`<p>${bcEscape(o.invoiceNumber||o.orderId)} <button class="link" onclick="invoice('${bcEscape(o.orderId||o.id)}')">Open</button></p>`).join('')||'<p>No invoices yet.</p>'}`;else if(section==='Reports')body=`<h2>Stored data report</h2><p>Orders: ${state.orders.length}</p><p>Gross totals: ${money(state.orders.reduce((n,o)=>n+(Number(o.grandTotal)||0),0))}</p><p>Local accounts: ${Object.keys(state.users).length}</p><p>Products: ${products.length}</p><button class="btn" onclick="exportCSV()">Export inventory</button>`;else if(section==='Settings')body='<h2>Settings unavailable</h2><p>Settings are not implemented in this static demo.</p>';else body='<p>Section unavailable.</p>';return `${nav()}<main class="wrap"><button class="link" onclick="state.adminSection=\'Dashboard\';go(\'admin\')">← Dashboard</button><section class="panel">${body}</section></main>`}
function updateProduct(id){const p=products.find(x=>x.id===Number(id)),name=(document.querySelector('#bc-name-'+id)?.value||'').trim(),price=Number(document.querySelector('#bc-price-'+id)?.value),stock=Number(document.querySelector('#bc-stock-'+id)?.value),rate=Number(document.querySelector('#bc-gst-'+id)?.value);if(!p||name.length<2||name.length>120||products.some(x=>x.id!==p.id&&x.name.toLowerCase()===name.toLowerCase())||!Number.isFinite(price)||price<=0||!Number.isInteger(stock)||stock<0||!bcGstOk(rate))return toast('Invalid name, price, stock or demo GST rate.');p.name=p.n=name;p.p=p.price=price;p.stock=stock;p.gstRate=rate;p.old=Math.max(p.old,price);p.originalPrice=p.old;p.discount=Math.max(0,Math.round((1-price/p.old)*100));p.description=bcDescription(p);save();state.adminSection='Products';go('admin')}
function createProduct(){const name=(document.querySelector('#bc-new-name')?.value||'').trim(),category=document.querySelector('#bc-new-category')?.value,brand=(document.querySelector('#bc-new-brand')?.value||'').trim(),price=Number(document.querySelector('#bc-new-price')?.value),stock=Number(document.querySelector('#bc-new-stock')?.value),gstRate=Number(document.querySelector('#bc-new-gst')?.value);if(name.length<2||name.length>120||!categories.some(x=>x[0]===category)||!brand||brand.length>80||products.some(p=>p.name.toLowerCase()===name.toLowerCase())||!Number.isFinite(price)||price<=0||!Number.isInteger(stock)||stock<0||!bcGstOk(gstRate))return toast('Invalid product fields.');const id=Math.max(...products.map(p=>p.id))+1,old=Math.round(price*1.2),p={id,n:name,name,b:brand,brand,c:category,category,p:price,price,old,originalPrice:old,stock,r:4.5,rating:4.5,reviewCount:0,discount:17,gstRate,hsn:'Unverified sample',sku:`BC-${String(id).padStart(4,'0')}`,icon:'🛍️',image:'',description:''};p.description=bcDescription(p);p.image=productFallback(p);products.push(p);save();toast('Product saved in this browser.');state.adminSection='Products';go('admin')}
function createCoupon(){const code=(document.querySelector('#bc-coupon-code')?.value||'').trim().toUpperCase(),type=document.querySelector('#bc-coupon-type')?.value,value=Number(document.querySelector('#bc-coupon-value')?.value),minRaw=document.querySelector('#bc-coupon-min')?.value,maxRaw=document.querySelector('#bc-coupon-max')?.value,expiry=document.querySelector('#bc-coupon-expiry')?.value||'',limitRaw=document.querySelector('#bc-coupon-limit')?.value,perRaw=document.querySelector('#bc-coupon-per-customer')?.value,old=state.coupons[bcEditingCoupon],today=new Date().toISOString().slice(0,10);if(!/^[A-Z0-9_-]{3,24}$/.test(code)||bcEditingCoupon&&code!==bcEditingCoupon||!old&&state.coupons[code])return toast('Use a unique code of 3–24 letters, numbers, hyphens or underscores.');if(expiry&&expiry<today)return toast('Expiry date must be today or later.');const c={...(old||{}),type,value,active:old?.active!==false,uses:Number(old?.uses||0),usageByUser:old?.usageByUser||{},maxPerCustomer:perRaw===''?1:Number(perRaw)};if(minRaw==='')delete c.min;else c.min=Number(minRaw);if(maxRaw==='')delete c.max;else c.max=Number(maxRaw);if(expiry)c.expiry=expiry;else delete c.expiry;if(limitRaw==='')delete c.maxUses;else c.maxUses=Number(limitRaw);if(!bcCouponOk(c))return toast('Check coupon type, value and limits.');state.coupons[code]=c;bcEditingCoupon='';save();state.adminSection='Coupons';go('admin')}
function editCoupon(code){if(!Object.hasOwn(state.coupons,code))return toast('Coupon not found.');bcEditingCoupon=code;state.adminSection='Coupons';go('admin')}
function cancelCouponEdit(){bcEditingCoupon='';state.adminSection='Coupons';go('admin')}
function toggleCoupon(code){const c=state.coupons[code];if(!c)return toast('Coupon not found.');c.active=c.active===false;save();state.adminSection='Coupons';go('admin')}
function generateCouponCode(){let code='';do{const bytes=new Uint8Array(6);crypto.getRandomValues(bytes);code='BILL'+Array.from(bytes,x=>(x%36).toString(36)).join('').toUpperCase()}while(state.coupons[code]);const input=document.querySelector('#bc-coupon-code');if(input)input.value=code;else toast('Open coupon creation before generating a code.')}
function applyCoupon(){const code=(document.querySelector('#coupon')?.value||'').trim().toUpperCase(),c=state.coupons?.[code],subtotal=state.cart.reduce((n,x)=>n+(products.find(p=>p.id===x.id)?.p||0)*x.q,0);if(!c||!bcCouponAvailable(c,state.user?.id))return toast('Coupon is invalid, inactive, expired, or its usage limit has been reached.');if(subtotal<Number(c.min||0))return toast(`Minimum spend is ${money(c.min)}.`);state.coupon=code;save();go('cart')}
function removeCoupon(){state.coupon='';save();go('cart')}
function add(id){if(!state.user||state.user.role==='admin')return go('login');const p=products.find(x=>x.id===Number(id)),c=state.cart.find(x=>x.id===Number(id));if(!validProduct(p)||!p.stock)return toast('Product unavailable.');if(c){if(c.q>=p.stock)return toast('Stock limit reached.');c.q++}else state.cart.push({id:p.id,q:1});save();go('cart')}
function wish(id){if(!state.user||state.user.role==='admin')return go('login');id=Number(id);state.wish=state.wish.includes(id)?state.wish.filter(x=>x!==id):[...state.wish,id];save();loadRoute()}
function qty(id,d){const c=state.cart.find(x=>x.id===Number(id)),p=products.find(x=>x.id===Number(id));if(!c||!p)return toast('Cart item unavailable.');if(c.q+Number(d)<1)return remove(id);if(c.q+Number(d)>p.stock)return toast('Stock limit reached.');c.q+=Number(d);save();go('cart')}
function remove(id){state.cart=state.cart.filter(x=>x.id!==Number(id));save();go('cart')}
function buyAgain(id){const o=state.orders.find(x=>(x.orderId||x.id)===id&&x.userId===state.user?.id);if(!o)return toast('Order not found.');for(const i of o.items||[]){const p=products.find(x=>x.id===Number(i.id));if(!p?.stock)continue;const q=Math.min(Number(i.quantity||i.q)||1,p.stock),c=state.cart.find(x=>x.id===p.id);if(c)c.q=Math.min(c.q+q,p.stock);else state.cart.push({id:p.id,q})}save();go('cart')}
function search(value){const q=String(value||'').trim();if(location.hash.includes('/shop')){shopFilters.query=q;renderShopGrid();return}if(!q)return loadRoute();const found=products.filter(p=>`${p.name} ${p.brand} ${p.category}`.toLowerCase().includes(q.toLowerCase()));document.querySelector('#app').innerHTML=`${nav()}<main class="wrap"><h2>Results for “${bcEscape(q)}” (${found.length})</h2>${found.length?`<div class="grid">${found.map(productCard).join('')}</div>`:'<div class="panel empty">No products found.</div>'}</main>`;const input=document.querySelector('#search');if(input){input.value=q;input.focus();input.setSelectionRange(q.length,q.length)}}
function filterPrice(v){shopFilters.max=Number(v);renderShopGrid()}function filterStock(v){shopFilters.stock=!!v;renderShopGrid()}function sortProducts(v){shopFilters.sort=String(v);renderShopGrid()}
function exportCSV(){const quote=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"',csv=[['SKU','Name','Category','Price','Demo GST','Stock'],...products.map(p=>[p.sku,p.name,p.category,p.p,p.gstRate,p.stock])].map(r=>r.map(quote).join(',')).join('\r\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='billcart-inventory-demo.csv';a.click();URL.revokeObjectURL(a.href)}
function adminPanel(section){if(state.user?.role!=='admin')return go('login');state.adminSection=section;go('admin')}
function go(page,arg,replace=false){const route=page+(arg!==undefined&&arg!==null&&arg!==''?'/'+encodeURIComponent(String(arg)):'');if(!replace)history.pushState({route},'',location.pathname+'#/'+route);const views={home:()=>home(),shop:()=>shop(arg||''),product:()=>details(arg),cart:()=>cart(),wishlist:()=>wishlist(),login:()=>login(),register:()=>registerDemo(),dashboard:()=>dashboard(),account:()=>myAccount(),checkout:()=>checkout(),orders:()=>arg?invoice(String(arg)):orders(),admin:()=>state.adminSection&&state.adminSection!=='Dashboard'?adminWorkspace(state.adminSection):admin(),invoice:()=>invoice(String(arg||'')),success:()=>success(String(arg||'')),tracking:()=>trackOrder(String(arg||'')),offers:()=>offers(),compare:()=>comparePage(arg)};const render=views[page];if(!render)document.querySelector('#app').innerHTML=notFound();else{const result=render();if(typeof result==='string')document.querySelector('#app').innerHTML=result}window.scrollTo(0,0)}
function loadRoute(){const parts=(location.hash.replace(/^#\/?/,'')||'home').split('/').map(x=>{try{return decodeURIComponent(x)}catch{return ''}}),page=parts[0],arg=parts[1];if(page==='invoice'||page==='orders'&&arg)return invoice(arg);if(page==='product')return document.querySelector('#app').innerHTML=details(arg);if(page==='tracking')return document.querySelector('#app').innerHTML=trackOrder(arg);const views={home:()=>home(),shop:()=>shop(arg||''),cart:()=>cart(),wishlist:()=>wishlist(),login:()=>login(),register:()=>registerDemo(),dashboard:()=>dashboard(),account:()=>myAccount(),checkout:()=>checkout(),orders:()=>orders(),admin:()=>state.adminSection&&state.adminSection!=='Dashboard'?adminWorkspace(state.adminSection):admin(),success:()=>success(arg),offers:()=>offers(),compare:()=>comparePage(arg)};document.querySelector('#app').innerHTML=views[page]?views[page]():notFound()}
if(!backendMode){window.addEventListener('popstate',loadRoute);window.addEventListener('hashchange',loadRoute);loadRoute()}

function downloadInvoicePdf(id){
  const o=state.orders.find(x=>(x.orderId||x.id)===id&&(state.user?.role==='admin'||x.userId===state.user?.id));
  if(!o)return toast('Invoice not found for this account.');
  const b=o.bill||{sub:o.subtotal||0,coupon:o.couponDiscount||0,taxable:o.taxableAmount||0,cgst:o.cgst??(o.gst||0)/2,sgst:o.sgst??(o.gst||0)/2,delivery:o.deliveryCharge||0,total:o.grandTotal||0};
  const ascii=v=>String(v??'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^\x20-\x7e]/g,'?');
  const pdfText=v=>ascii(v).replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)');
  const fmt=n=>Number(n||0).toFixed(2),items=o.items||[],base=items.reduce((n,i)=>n+(Number(i.unitPrice??i.price)||0)*(Number(i.quantity||i.q)||0),0);
  const lines=['BillCart - Demo Invoice',`Invoice: ${o.invoiceNumber||o.id}`,`Order: ${o.orderId||o.id}`,`Invoice date: ${o.createdAt||'Not recorded'}`,'','Sample invoice only; tax identifiers and rates are unverified.',`Customer: ${o.customer||'Customer'}`,`Billing / delivery address: ${[o.deliveryAddress?.address,o.deliveryAddress?.city,o.deliveryAddress?.state,o.deliveryAddress?.pincode].filter(Boolean).join(', ')||'Not recorded'}`,`Phone: ${o.deliveryAddress?.phone||'Not recorded'}`,'','SKU | Product | Qty | Unit INR | Line INR | GST | Tax INR'];
  for(const i of items){const q=Number(i.quantity||i.q)||0,p=Number(i.unitPrice??i.price)||0,r=bcGstOk(i.gstRate)?Number(i.gstRate):18,gross=p*q,share=base?Number(b.coupon||0)*gross/base:0,taxable=Math.max(0,gross-share),tax=taxable*r/100;lines.push(`${i.sku||i.id||''} | ${i.name||'Product'} | ${q} | ${fmt(p)} | ${fmt(gross)} | ${r}% | ${fmt(tax)}`);if(i.hsn)lines.push(`  Sample HSN: ${i.hsn} (unverified)`)}
  lines.push('',`Subtotal: INR ${fmt(b.sub)}`,`Product savings: INR ${fmt(o.productDiscount)}`,`Coupon ${o.couponCode||''}: -INR ${fmt(b.coupon)}`,`Taxable amount: INR ${fmt(b.taxable)}`,`CGST: INR ${fmt(b.cgst)}`,`SGST: INR ${fmt(b.sgst)}`,`Delivery: INR ${fmt(b.delivery)}`,`Total: INR ${fmt(b.total)}`,`Payment method: ${o.paymentMethod||'Not recorded'}`,`Payment status: ${o.paymentStatus||'Not recorded'}`,'','Demo document only. No payment was processed; this is not a government tax invoice.');
  const wrapped=[];for(const line of lines){if(!line){wrapped.push('');continue}for(let i=0;i<line.length;i+=88)wrapped.push(line.slice(i,i+88))}
  const perPage=49,pages=[];for(let i=0;i<wrapped.length;i+=perPage)pages.push(wrapped.slice(i,i+perPage));if(!pages.length)pages.push([]);
  const objects=[];objects[1]='<< /Type /Catalog /Pages 2 0 R >>';objects[3]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>';const kids=[];
  pages.forEach((page,index)=>{const pageId=4+index*2,streamId=pageId+1;kids.push(`${pageId} 0 R`);const text=['BT','/F1 9 Tf','44 790 Td','13 TL',...page.flatMap((line,i)=>[`${i?'T* ':''}(${pdfText(line)}) Tj`]),`T* (Page ${index+1} of ${pages.length}) Tj`,'ET'].join('\n');objects[pageId]=`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R >> >> /Contents ${streamId} 0 R >>`;objects[streamId]=`<< /Length ${new TextEncoder().encode(text).length} >>\nstream\n${text}\nendstream`});
  objects[2]=`<< /Type /Pages /Kids [${kids.join(' ')}] /Count ${pages.length} >>`;
  let pdf='%PDF-1.4\n',offsets=[0];for(let id=1;id<objects.length;id++){offsets[id]=new TextEncoder().encode(pdf).length;pdf+=`${id} 0 obj\n${objects[id]}\nendobj\n`}const xref=new TextEncoder().encode(pdf).length;pdf+=`xref\n0 ${objects.length}\n0000000000 65535 f \n`;for(let id=1;id<objects.length;id++)pdf+=`${String(offsets[id]).padStart(10,'0')} 00000 n \n`;pdf+=`trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;
  const blob=new Blob([pdf],{type:'application/pdf'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`BillCart-${ascii(o.invoiceNumber||o.id).replace(/[^A-Za-z0-9_-]/g,'_')}.pdf`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)
}
